function resolveEventWeaponFamily(world, weaponId) {
  if (!(weaponId > 0) || !world.isAlive(weaponId)) return "";
  const info = world.get(weaponId, ItemInfo);
  return String(info?.weaponFamily || resolveWeaponFamily(info || {}) || "");
