function setup() {
  // Ensure bump targets are walkable (hostile melee gate checks tile walkability).
  clearAll();
  loadChunk(0, 0, new Uint8Array(CHUNK_SIZE * CHUNK_SIZE).fill(TILE_FLOOR));

