const cmds = [
  "rtk rg -n \"world\\.get\\([^\\n]*Turn|TurnState|turnNumber|world\\.step|world\\.tick|currentTurn|turn\" src/rules src/main | head -160",
  "rtk rg -n \"remove\\(.*Intent|world\\.query\\(.*Intent|registerSystem\\(.*after:.*ai|phase.*ai\" src/rules/systems src/main tests | head -180",
  "rtk sed -n '780,830p' src/rules/systems/aiChaseSystem.js",
  "rtk sed -n '1,120p' src/rules/systems/intentValidationSystem.js",
  "rtk sed -n '1,130p' src/rules/systems/waitSystem.js",
  "rtk sed -n '1,180p' tests/aiPolicyChaseIntegration.test.mjs"
];
const r = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/home/pjensen/Repos/JSHack",yield_time_ms:10000,max_output_tokens:12000})));
for (let i=0;i<r.length;i++) text(`--- ${cmds[i]} ---\n${r[i].output}`);

