      && Number.isInteger(rec.targetId)
      && Number.isInteger(rec.targetX)
      && Number.isInteger(rec.targetY)
      && Number.isInteger(rec.dx)
      && Number.isInteger(rec.dy)
      && Number.isInteger(rec.expiresAtStep);
  },
});

