    .sort((a, b) => b[1] - a[1])
    .map(([k, v]) => `${k}:${v}`)
    .slice(0, 3)
    .join(' ');

  return { label, pHitRate: pHitRate + '%', pAvgDmg, pMaxDmg: String(r.playerMaxDmg),
    mHitRate: mHitRate + '%', mAvgDmg, avgTurns, winRate: winRate + '%', avgHpLeft, effects };
}

