// rules/utils/speedGate.js
// Canonical speed-gating check shared by all AI systems.

import { Speed } from "../components/Speed.js";
import { capabilityStrength, hasCapability, statusStrength } from "./statusFacade.js";

/**
 * Returns true when the entity is allowed to act this tick.
 * Accounts for base speed cadence, frozen-status slow, and hastened buff.
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} id
 * @returns {boolean}
 */
export function canActThisTurn(world, id) {
  // Stasis is an absolute action lock, not a cadence modifier. Keep this
  // gate authoritative for every AI producer so direct AI callbacks (for
  // example LOS abilities) cannot act before intent validation runs.
  if (hasCapability(world, id, "action_locked")) return false;

  const spd = world.get(id, Speed);
  let actEvery = (spd && spd.actEvery > 1) ? spd.actEvery : 1;
  const frostStacks = Math.min(3, capabilityStrength(world, id, "frozen"));
  if (frostStacks > 0) actEvery = actEvery * (1 + frostStacks);
  const hasteStacks = Math.min(3, statusStrength(world, id, "hastened"));
  if (hasteStacks > 0 && actEvery > 1) actEvery = Math.max(1, actEvery - hasteStacks);
  return !(actEvery > 1 && ((world.step + id) % actEvery) !== 0);
}
92:export function playerEntity(world) {
import { Position } from "../components/Position.js";
import { ItemInfo } from "../components/ItemInfo.js";
import { GroundStackOrder } from "../components/GroundStackOrder.js";
import { Player } from "../components/Player.js";
import { Inventory } from "../components/Inventory.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { Collider } from "../components/Collider.js";
import { Vitality } from "../components/Vitality.js";
import { Faction } from "../components/Faction.js";
import { Anatomy } from "../components/Anatomy.js";
import { AggroState } from "../components/AggroState.js";
import { HazardArea } from "../components/HazardArea.js";
import { Not } from "../../lib/ecs-js/core.js";
import { isWalkable } from "../environment/dungeon/tileMap.js";
import { manhattanScalar } from "./distance.js";
import { entitiesAtPoint } from "./spatialIndex.js";

// ── Shared defined-query registry ─────────────────────────────────────────────
// WeakMap ensures each world instance gets its own set of handles, so tests
// that create multiple worlds never share stale state across runs.

/** @type {WeakMap<object, ReturnType<typeof _buildHandles>>} */
const _qCache = new WeakMap();

function _buildHandles(world) {
  return {
    allPositions:     world.defineQuery(Position),
    namedPositions:   world.defineQuery(Position, NamedIdentity),
    playerPosInv:     world.defineQuery(Player, Position, Inventory),
    positionFaction:  world.defineQuery(Position, Faction),
    playerPos:       world.defineQuery(Player, Position),
    factionActors:   world.defineQuery(Faction, Position, Vitality),
    aggroPositioned: world.defineQuery(AggroState, Position, Not(Player)),
    enemyListeners:  world.defineQuery(Anatomy, AggroState, Faction, Position)
                       .where((anat, aggro, fac) => fac.key === "enemy"),
    hazardAreas:     world.defineQuery(Position, HazardArea),
  };
}

function _q(world) {
  if (!_qCache.has(world)) _qCache.set(world, _buildHandles(world));
  return _qCache.get(world);
}

// ── Public query iterators ─────────────────────────────────────────────────────

/** All entities with Player + Position. */
export function queryPlayerPos(world)       { return _q(world).playerPos(); }

/** All entities with Position. */
export function queryAllPositions(world)    { return _q(world).allPositions(); }

/** All entities with Position + NamedIdentity. */
export function queryNamedPositions(world)  { return _q(world).namedPositions(); }

/** All players with Position + Inventory. */
export function queryPlayerPosInv(world)    { return _q(world).playerPosInv(); }

/** All entities with Position + Faction. */
export function queryPositionFaction(world) { return _q(world).positionFaction(); }

/** All entities with Faction + Position + Vitality. */
export function queryFactionActors(world)   { return _q(world).factionActors(); }

/** All non-player entities with AggroState + Position. */
export function queryAggroPositioned(world) { return _q(world).aggroPositioned(); }

/** All enemy entities with Anatomy + AggroState + Faction + Position. */
export function queryEnemyListeners(world)  { return _q(world).enemyListeners(); }

/** All entities with Position + HazardArea. */
export function queryHazardAreas(world)     { return _q(world).hazardAreas(); }

// ── Utility functions ──────────────────────────────────────────────────────────

export function itemsAt(world, x, y) {
  const ids = entitiesAtPoint(world, x, y);
  const rows = [];
  let idx = 0;
  for (const id of ids) {
    if (!world.has(id, ItemInfo)) continue;
    const seq = Number(world.get(id, GroundStackOrder)?.seq || 0) | 0;
    rows.push({ id, seq, idx: idx++ });
  }
  rows.sort((a, b) => {
    if (a.seq !== b.seq) return b.seq - a.seq;
    return a.idx - b.idx;
  });
  return rows.map((row) => row.id);
}

export function playerEntity(world) {
  for (const [id, _pl, pos] of queryPlayerPos(world)) {
    if (pos && Number.isInteger(pos.x) && Number.isInteger(pos.y)) {
      return { id, pos: { x: pos.x, y: pos.y } };
    }
  }
  return null;
}

import { defineComponent } from "../../lib/ecs-js/index.js";

export const AGGRO_LEVELS = Object.freeze({
  unaware:  "unaware",   // no knowledge of any threat; idle
  curious:  "curious",   // heard something faint; investigating last-known position
  alerted:  "alerted",   // lost LOS or heard loud noise; actively searching
  hunting:  "hunting",   // has direct LOS; pursuing and attacking
});

// Default search budgets (turns to spend searching before downgrading alert level)
export const SEARCH_TURNS_HUNTING_GRACE = 10;   // turns of alerted state after losing LOS
export const SEARCH_TURNS_ALERTED       = 10;   // turns alerted → curious downgrade
export const SEARCH_TURNS_CURIOUS       = 6;    // turns curious → unaware downgrade

/**
 * AggroState — per-entity awareness of a threat (typically the player).
 *
 * alertLevel: current awareness tier (see AGGRO_LEVELS).
 * lastKnownX/Y: last recorded position of the target (updated each hunting tick).
 * targetId: current live aggro target while hunting; 0 means no selected target.
 * targetReason: why targetId was selected (sight, conflict, taunt, etc.).
 * highestThreatId: source with the highest current ThreatEntry value.
 * forcedTargetId / forcedUntilTurn: hard taunt lock.
 * threatLockUntilTurn: soft switch lock to prevent threshold chatter.
 * lastTargetSwitchTurn: turn of the last target change.
 * threatState: display/debug summary ("none", "stable", "unstable", "locked").
 * lastKnownMoveDx/Dy: last observed movement direction of the target.
 *   Used by intel ≥ 8 monsters to anticipate escape routes on LOS break.
 * nextSightAlertTurn: next world step when a non-hunting sight alert may fire.
 * searchTurnsLeft: countdown before downgrading to the next lower tier.
 * retreating: true while the creature is below its retreat HP threshold and
 *             actively fleeing rather than chasing. Cleared when HP recovers.
 * patrolDx/patrolDy: current patrol heading used when unaware and intelligence > 3.
 *   0,0 means "not yet assigned" — aiScurrySystem picks a direction on first use.
 *
 * Managed by aiChaseSystem, aiScurrySystem, and soundPropagationSystem.
 */
export const AggroState = defineComponent("AggroState", {
  alertLevel:        AGGRO_LEVELS.unaware,
  targetId:          0,
  targetReason:      "",
  highestThreatId:   0,
  forcedTargetId:    0,
  forcedUntilTurn:   0,
  threatLockUntilTurn: 0,
  lastTargetSwitchTurn: 0,
  threatState:       "none",
  lastKnownX:        0,
  lastKnownY:        0,
  lastKnownMoveDx:   0,
  lastKnownMoveDy:   0,
  nextSightAlertTurn: 0,
  searchTurnsLeft:   0,
  retreating:        false,
  patrolDx:          0,
  patrolDy:          0,
});

import "../../../../src/content/items/index.js";
import "../../../../src/content/monsters/index.js";
import "../../../../src/content/interactables/index.js";
import { installContent } from "../../../../src/content/install.js";
import { World } from "../../../../src/lib/ecs-js/index.js";
import { configureWorld } from "../../../../src/main/scheduler.js";
import { createPlayer } from "../../../../src/rules/archetypes/Player.js";
import { spawnMonsterEntity } from "../../../../src/rules/utils/spawnMonsterEntity.js";
import { createItemById } from "../../../../src/rules/utils/itemFactory.js";
import { getMonster, resolveMonsterMaxHp } from "../../../../src/rules/data/monsters.js";
import { Brain } from "../../../../src/rules/components/Brain.js";
import { AggroState, AGGRO_LEVELS } from "../../../../src/rules/components/AggroState.js";
import { Equipment } from "../../../../src/rules/components/Equipment.js";
import { Position } from "../../../../src/rules/components/Position.js";
import { Vitality } from "../../../../src/rules/components/Vitality.js";
import { Faction } from "../../../../src/rules/components/Faction.js";
import { MoveIntent } from "../../../../src/rules/components/Intents/MoveIntent.js";
import { WaitIntent } from "../../../../src/rules/components/Intents/WaitIntent.js";
import { AttackIntent } from "../../../../src/rules/components/Intents/AttackIntent.js";
import { CastSpellIntent } from "../../../../src/rules/components/Intents/CastSpellIntent.js";
import { RangedAttackIntent } from "../../../../src/rules/components/Intents/RangedAttackIntent.js";
import { clearAll, loadChunk } from "../../../../src/rules/environment/dungeon/tileMap.js";
import { CHUNK_SIZE, TILE_FLOOR, TILE_WALL } from "../../../../src/rules/environment/dungeon/constants.js";

installContent();

const SEED = 186;
const MAX_TURNS = 32;
const ROOM_ORIGIN = { x: 0, y: 0 };
const INCLUDE_TRACE = Deno.args.includes("--trace");

function loadFlatRoom({ corridor = false } = {}) {
  clearAll();
  const tiles = new Uint8Array(CHUNK_SIZE * CHUNK_SIZE);
  tiles.fill(TILE_FLOOR);
  if (corridor) {
    for (let y = 0; y < CHUNK_SIZE; y++) {
      if (y === 10) continue;
      tiles[y * CHUNK_SIZE + 11] = TILE_WALL;
      tiles[y * CHUNK_SIZE + 13] = TILE_WALL;
    }
  }
  loadChunk(ROOM_ORIGIN.x, ROOM_ORIGIN.y, tiles);
}

function monsterParams(identity, depth = 2) {
  const def = getMonster(identity);
  if (!def) throw new Error(`unknown monster: ${identity}`);
  return {
    name: def.name,
    identity: def.id,
    maxHp: resolveMonsterMaxHp(def, depth),
    faction: "enemy",
    accuracyDerived: def.attack || 0,
    damagePowerDerived: def.attack || 0,
    evadeDerived: def.defense || 0,
    naturalDamageDice: def.damageDice || "1d2",
    sizeClass: def.sizeClass,
    massKg: def.massKg || 80,
    resistances: def.resistances || {},
    speed: def.speed || 1,
    learnedSpellIds: def.learnedSpellIds || [],
  };
}

function nearestGoblin(world, playerId, goblins) {
  const player = world.get(playerId, Position);
  let best = 0;
  let bestDistance = Infinity;
  for (const id of goblins) {
    const vit = world.get(id, Vitality);
    const pos = world.get(id, Position);
    if (!world.isAlive(id) || !vit || vit.hp <= 0 || !pos) continue;
    const distance = Math.max(Math.abs(pos.x - player.x), Math.abs(pos.y - player.y));
    if (distance < bestDistance) {
      best = id;
      bestDistance = distance;
    }
  }
  return best;
}

function queueAdjacentAttack(world, playerId, targetId) {
  const player = world.get(playerId, Position);
  const target = world.get(targetId, Position);
  if (!player || !target) return false;
  const distance = Math.max(Math.abs(target.x - player.x), Math.abs(target.y - player.y));
  if (distance > 1) return false;
  world.add(playerId, AttackIntent, { targetId });
  return true;
}

function queuePlayerAction(world, playerId, goblins, strategy, turn) {
  const player = world.get(playerId, Position);
  const targetId = nearestGoblin(world, playerId, goblins);
  const target = targetId ? world.get(targetId, Position) : null;

  if (strategy === "standing") {
    if (!queueAdjacentAttack(world, playerId, targetId)) world.add(playerId, WaitIntent, {});
    return;
  }

  if (strategy === "ranged") {
    if (targetId && target) {
      world.add(playerId, RangedAttackIntent, {
        targetId,
        toX: target.x,
        toY: target.y,
      });
    } else {
      world.add(playerId, WaitIntent, {});
    }
    return;
  }

  if (strategy === "disable") {
    if (targetId && target && turn % 4 === 1) {
      world.add(playerId, CastSpellIntent, {
        spellId: "entangle",
        targetId,
        x: target.x,
        y: target.y,
      });
      return;
    }
  }

  if (strategy === "retreat") {
    world.add(playerId, MoveIntent, { dx: -1, dy: 0 });
    return;
  }

  if (targetId && queueAdjacentAttack(world, playerId, targetId)) return;
  world.add(playerId, MoveIntent, { dx: 1, dy: 0 });
}

function snapshot(world, playerId, goblins) {
  const playerPos = world.get(playerId, Position);
  const playerVit = world.get(playerId, Vitality);
  return {
    step: world.step | 0,
    player: {
      x: playerPos?.x ?? null,
      y: playerPos?.y ?? null,
      hp: playerVit?.hp ?? 0,
    },
    goblins: goblins.map((id) => {
      const pos = world.get(id, Position);
      const vit = world.get(id, Vitality);
      return {
        id,
        alive: world.isAlive(id) && (vit?.hp || 0) > 0,
        x: pos?.x ?? null,
        y: pos?.y ?? null,
        hp: vit?.hp ?? 0,
      };
    }),
  };
}

function runScenario({ name, strategy, policy, corridor = false }) {
  loadFlatRoom({ corridor });
  const world = new World({ seed: SEED });
  configureWorld(world);
  world.step = 0;

  const playerId = createPlayer(world, {
    x: strategy === "retreat" ? 12 : 10,
    y: 10,
    name: "Probe",
    identity: "player_probe",
    maxHp: 33,
    maxStamina: 130,
  });
  const playerBrain = world.get(playerId, Brain);
  world.set(playerId, Brain, {
    ...playerBrain,
    intelligence: 12,
    learnedSpellIds: ["entangle"],
    visionRange: 12,
  });

  const eq = world.get(playerId, Equipment);
  if (strategy === "ranged") {
    eq.ranged = createItemById(world, "bow_short");
    eq.ammo = createItemById(world, "ammo_arrows", { count: 40 });
  } else {
    eq.weapon = createItemById(world, "axe_heavy");
  }

  const goblins = [];
  for (const [x, y] of [[15, 9], [16, 10], [15, 11]]) {
    const id = spawnMonsterEntity(world, { ...monsterParams("goblin"), x, y });
    const aggro = world.get(id, AggroState);
    world.set(id, AggroState, {
      ...aggro,
      alertLevel: AGGRO_LEVELS.hunting,
      lastKnownX: 10,
      lastKnownY: 10,
      targetId: playerId,
    });
    const brain = world.get(id, Brain);
    world.set(id, Brain, {
      ...brain,
      intelligence: policy ? 8 : 4,
      visionRange: 12,
    });
    goblins.push(id);
  }

  const trace = [];
  for (let turn = 1; turn <= MAX_TURNS; turn++) {
    queuePlayerAction(world, playerId, goblins, strategy, turn);
    world.tick(1);
    trace.push(snapshot(world, playerId, goblins));
    const playerVit = world.get(playerId, Vitality);
    if (!playerVit || playerVit.hp <= 0) break;
    if (trace.at(-1).goblins.every((g) => !g.alive)) break;
  }

  return {
    name,
    strategy,
    policy,
    corridor,
    result: trace.at(-1),
    trace,
  };
}

const scenarios = [
  { name: "chase only", strategy: "chase", policy: false },
  { name: "chase plus policy", strategy: "chase", policy: true },
  { name: "standing still", strategy: "standing", policy: false },
  { name: "retreating into corridor", strategy: "retreat", policy: true, corridor: true },
  { name: "disabling option", strategy: "disable", policy: true },
  { name: "ranged option", strategy: "ranged", policy: false },
];

for (const scenario of scenarios) {
  const result = runScenario(scenario);
  const final = result.result;
  const report = {
    name: result.name,
    strategy: result.strategy,
    policy: result.policy,
    corridor: result.corridor,
    turns: result.trace.length,
