    }

    // Cast time: begin channeling instead of immediate cast
    const castTime = Number(resolvedSpell.castTime || 0) | 0;
    const castTime = Number(resolvedSpell.castTime || 0) | 0;
    if (castTime > 0 && !fromChanneling) {
