/** @param {any} world */
export function aiChaseSystem(world) {
  // Locate the player.
  const _player = playerEntity(world);
  if (!_player) return;
  const playerId  = _player.id;
  const playerPos = _player.pos;

  // Lazily built blocking map for LOS checks (built once, shared this tick).
  let _isBlocked = null;
