    const ni = world.get(id, NamedIdentity);
    const def = ni ? getMonster(String(ni.identity || "")) : null;
    const fac = world.get(id, Faction);
    const canChase = !!fac && fac.key === "enemy";
    if (!canChase && !def?.alertOnSight) return;

