export function clearThreatFromSource(world, sourceId, opts = {}) {
  const source = normalizeId(sourceId);
  if (!source) return 0;
  let changed = 0;
  for (const [ownerId, aggro] of world.query(AggroState)) {
    const found = findThreatEntry(world, ownerId, source);
