  });

  world.on('spell:heal', ({ actor, reason, amount }) => {
    if (nameOfEntity(actor) !== 'You') return;
    if (reason === 'full_health' || Number(amount || 0) <= 0) {
      log('The healing spell finds you whole. The magic fades, unused.', 'system');
